class Revoker:
    def __init__(self, target):
        self.target = target
        self.enabled = True

    def call(self, request):
        if not self.enabled:
            raise PermissionError("revoked")
        return self.target.call(request)

    def revoke(self):
        self.enabled = False

# Grant only attenuated authority.
